/** Draw one of ART.big at (x, y), its top left: opts { fx, fy (flip the whole sprite), prio (default 3), pal (every
 * part in this sprite palette, e.g. a hit flash) }. Each part is one spr() (generated by art.py). */
function bigSprite(b, x, y, opts = {}) {
  const fx = !!opts.fx, fy = !!opts.fy, prio = opts.prio ?? 3;
  for (const [dx, dy, t, size, pal, f] of b.parts) {
    spr(t, x + (fx ? b.w - dx - size : dx), y + (fy ? b.h - dy - size : dy),
      { size, pal: opts.pal ?? pal, fx: fx !== !!(f & 1), fy: fy !== !!(f & 2), prio });
  }
}
/** In scanline(y): set the CGRAM entry of a gradient from ART.gradients to its colour for line y (generated by art.py). */
function gradientLine(g, y) {
  const v = g.lines[y - g.y0];
  if (v !== undefined) color(g.entry, v & 31, (v >> 5) & 31, v >> 10);
}
// END ART

const FEET = 70;            // the rig's canvas: the soles are this many pixels below its top
const GROUND = 204;         // where his feet are on the screen
const SPEED = { idle: 30, walk: 7, punch: 5, kick: 6 };   // frames each animation frame is shown
let x = 100, facing = 1, act = 'idle', frame = 0, timer = 0;

function init() {
  bg(2, { mx: ART.scenes.city.mx, my: 0, mw: 32, mh: 28, x: 0, y: 12, wrap: true, show: true });
  bg(1, { mx: ART.scenes.fence.mx, my: 0, mw: 32, mh: 28, x: 0, y: 0, wrap: true, show: true });
  bg(0, { mx: ART.scenes.ground.mx, my: 0, mw: 32, mh: 28, x: 0, y: 0, wrap: true, show: true });
}

function start(a) { if (act !== a) { act = a; frame = 0; timer = 0; } }

function update() {
  const busy = (act === 'punch' || act === 'kick');
  if (!busy) {
    if (btnp(A)) start('punch');
    else if (btnp(B)) start('kick');
    else if (btn(LEFT) || btn(RIGHT)) {
      facing = btn(LEFT) ? -1 : 1;
      x = clamp(x + facing * 1.2, -20, 200);
      start('walk');
    } else start('idle');
  }
  const n = ART.anims[act].length;
  if (++timer >= SPEED[act]) {
    timer = 0;
    frame++;
    if (frame >= n) { frame = 0; if (busy) start('idle'); }
  }
}

function draw() {
  cls();
  // his shadow (sprite palette 4) is subtracted from the pavement under him
  blend({ layers: ['spr'], op: 'sub' });
  const b = ART.big[ART.anims[act][frame]];
  bigSprite(b, flr(x), GROUND - FEET, { fx: facing < 0, prio: 2 });
  bigSprite(ART.big.shadow, flr(x) + (facing < 0 ? b.w - 30 - 40 : 30) - 4, GROUND - 4, { prio: 2 });
  print('WALK  A:PUNCH  B:KICK', 128 - 21 * 4, 214, ART.colors.WHITE);
}

function scanline(y) { gradientLine(ART.gradients.sky, y); }
